#!/usr/bin/env bash
# green_stop InterFuser diagnosis runs in the benchmark harness (protocol v2), adapter defaults with the speed input pinned to "forward".
#   PY=<marshal env python> bash reports/scoring_validity_audit/interfuser_greenstop/scripts/run_greenstop.sh
# Run from the checkout root. run_protocol_v2.py starts and kills CARLA. Finished episodes are skipped on re-run.
# Do not edit this file while it runs.
set -u
PY="${PY:-python}"
OUT=tmp/_greenstop_interfuser
# Pinned: forward speed input (the setting these runs were made with).
FWD='{"interfuser": {"speed_input": "forward"}}'
GREEN='{"traffic_light": {"state": "Green", "freeze": true}, "interfuser": {"speed_input": "forward"}}'
NOOFF=(--env MARSHAL_OFFICER_CONDITION=absent --env MARSHAL_INTERFUSER_VERBOSE=1 --env "MARSHAL_CONTROLLER_OVERRIDES=$GREEN")
# (1) A->B no officer, light frozen Green: green_stop seeds 0-4, the five other stations seeds 0-2
"$PY" scripts/run_protocol_v2.py --models interfuser --seeds 0 1 2 3 4 --scenarios green_stop \
  --out-root "$OUT/ab" --tag _noofficer_green --log "$OUT/ab/run_log.jsonl" "${NOOFF[@]}"
"$PY" scripts/run_protocol_v2.py --models interfuser --seeds 0 1 2 \
  --scenarios red_proceed signal_off unauthorized_go ambiguous_gesture fake_vest_director \
  --out-root "$OUT/ab" --tag _noofficer_green --log "$OUT/ab/run_log.jsonl" "${NOOFF[@]}"
# (2) green_stop with the officer STOP directive (the leaderboard condition), seeds 0-2
"$PY" scripts/run_protocol_v2.py --models interfuser --seeds 0 1 2 --scenarios green_stop \
  --out-root "$OUT/officer" --log "$OUT/officer/run_log.jsonl" --env MARSHAL_INTERFUSER_VERBOSE=1 --env "MARSHAL_CONTROLLER_OVERRIDES=$FWD"
